mapper.update:
update student_material
material_type = #{materialType}, title = #{title}, content = #{content}, file_url = #{fileUrl},
where id = #{id}

mapper.select:
select sm.*, (case when se.id is null then 0 else 1 end) as evaluated, se.id as evaluation_id, se.score, se.content as evaluation_content, se.evaluation_time, se.teacher_user_id, u.real_name as teacher_real_name from student_material sm left join student_evaluation se on sm.id = se.material_id left join user u on se.teacher_user_id = u.id
and sm.student_user_id = #{studentUserId}
and sm.material_type = #{materialType}
and sm.title like concat('%',#{title},'%')
order by sm.submit_time desc

select sm.id, sm.student_user_id as studentUserId, sm.student_user_id as userId, s.student_no as studentNo, su.real_name as studentRealName, sm.material_type as materialType, sm.title, sm.submit_time as submitTime, (case when se.id is null then 0 else 1 end) as evaluated, se.id as evaluationId, se.score, se.evaluation_time as evaluationTime, se.teacher_user_id as teacherUserId, tu.real_name as teacherRealName from student_material sm join ts_guidance tg on tg.student_user_id = sm.student_user_id join students s on s.user_id = sm.student_user_id left join user su on su.id = sm.student_user_id left join student_evaluation se on se.material_id = sm.id left join user tu on tu.id = se.teacher_user_id
tg.teacher_user_id = #{teacherId}
and sm.material_type = #{dto.materialType}
and s.student_no like concat('%', #{dto.studentNo}, '%')
and su.real_name like concat('%', #{dto.realName}, '%')
and s.major_id = #{dto.majorId}
and s.class_id = #{dto.classId}
and (case when se.id is null then 0 else 1 end) = #{dto.evaluated}
order by sm.submit_time desc

select sm.id, sm.student_user_id as studentUserId, sm.student_user_id as userId, s.student_no as studentNo, su.real_name as studentRealName, sm.material_type as materialType, sm.title, sm.submit_time as submitTime, (case when se.id is null then 0 else 1 end) as evaluated, se.id as evaluationId, se.score, se.evaluation_time as evaluationTime, se.teacher_user_id as teacherUserId, tu.real_name as teacherRealName from student_material sm join students s on s.user_id = sm.student_user_id left join user su on su.id = sm.student_user_id left join student_evaluation se on se.material_id = sm.id left join user tu on tu.id = se.teacher_user_id
and sm.material_type = #{dto.materialType}
and s.university_id = #{dto.universityId}
and s.college_id = #{dto.collegeId}
and s.student_no like concat('%', #{dto.studentNo}, '%')
and su.real_name like concat('%', #{dto.realName}, '%')
and s.major_id = #{dto.majorId}
and s.class_id = #{dto.classId}
and (case when se.id is null then 0 else 1 end) = #{dto.evaluated}
order by sm.submit_time desc
